package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import static org.jlinalg.cli.StudyPublicEvidence.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;
import org.jlinalg.study.StudyFindingGroupingPolicy;
import org.jlinalg.study.StudyOperationExecutor.Context;
import org.jlinalg.study.StudyOperationExecutor.State;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class StudyFindingGroupingTest {
    @TempDir Path root;
    private Map<String,Object> reference(String coverage)throws Exception {
        if(!Files.exists(root.resolve("variants.tsv"))){Files.writeString(root.resolve("variants.tsv"),"variant_id\tchromosome\tposition\tref\talt\nrs1\t1\t100\tA\tG\nrs2\t1\t250\tA\tG\nrs3\t1\t400\tA\tG\nrs4\t1\t2000\tA\tG\nrs5\t1\t3000\tA\tG\nrs6\t1\t4000\tA\tG\n");Files.writeString(root.resolve("pairs.tsv"),"variant_a\tvariant_b\tr_squared\nrs1\trs2\t.81\nrs2\trs3\t.81\nrs1\trs3\t.49\n");}
        return new LinkedHashMap<>(Map.of("id","panel","genome_build","GRCh38","population","EUR","release","synthetic-1","hypotheses",List.of("H"),"variants","variants.tsv","pairs","pairs.tsv","coverage",coverage,"window_bp",200));
    }
    private Context context(String name,Map<String,Object> policy)throws Exception {
        var study=Map.<String,Object>of("project",Map.of("finding_grouping",policy,"manuscript_policy",Map.of("minimum_findings",3,"maximum_findings",5)),"datasets",List.of(Map.of("id","a","cohort","A","type","gwas","stage","association_results","genome_build","GRCh38","species","human","metadata",Map.of("ancestry","European"))),"hypotheses",List.of(Map.of("id","H","inputs",Map.of("discovery",List.of("a")),"analysis",Map.of("association",Map.of("model","ols"),"multiple_testing",Map.of("method","BH","alpha",.05)))));
        return new Context(root,Files.createDirectories(root.resolve(name)),Map.of("id",name,"type","finding_inventory","hypothesis","__study__","datasets",List.of("a")),study,Map.of(),Map.of());
    }
    private Map<String,Map<String,Object>> findings(){var out=new LinkedHashMap<String,Map<String,Object>>();for(String id:List.of("rs1","rs3","rs4","rs5","rs6"))out.put("H\u001f"+id,new LinkedHashMap<>(Map.of("finding_id","finding-"+id,"hypothesis","H","feature_id",id,"estimable",true,"significant",true,"candidate",true,"story_group","label-"+id)));return out;}
    private Map<String,List<Object>> observations(){var out=new LinkedHashMap<String,List<Object>>();for(String id:List.of("rs1","rs3","rs4","rs5","rs6"))out.put("H\u001f"+id,List.of(Map.of("primary",true,"operation_type","association","source_ids",List.of("statistical-source"))));return out;}
    private StudyFindingGrouping.Outcome apply(Context c)throws Exception {return StudyFindingGrouping.apply(c,findings(),observations(),Map.of(),new LinkedHashMap<>(),Map.of());}
    private static String component(StudyFindingGrouping.Outcome result,String id){return text(result.assignments().get("H\u001f"+id).get("component_id"));}
    @Test void transitiveLdUsesUnselectedReferenceMediatorsAndPreservesDistinctStoryLabels()throws Exception {
        var r=reference("complete_window");var c=context("transitive",Map.of("references",List.of(r),"maximum_distance_bp",200));var f=findings();String before=StudyAssistance.json(f);var sources=new LinkedHashMap<String,Map<String,Object>>();var result=StudyFindingGrouping.apply(c,f,observations(),Map.of(),sources,Map.of());assertEquals(true,result.summary().get("complete"));assertEquals(5,((Number)result.summary().get("matched_inventory_findings")).intValue());assertEquals(4,((Number)result.summary().get("components_with_findings")).intValue());assertEquals(component(result,"rs1"),component(result,"rs3"));assertNotEquals(component(result,"rs1"),component(result,"rs4"));assertEquals(3,result.assignments().get("H\u001frs1").get("reference_variant_members"));assertEquals(before,StudyAssistance.json(f));assertEquals(1,sources.size());assertTrue(result.outputs().contains("finding-grouping/finding-membership.tsv"));assertTrue(StudyFindingGrouping.CAVEAT.contains("need not all meet"));
    }
    @Test void componentIdentityDoesNotDependOnInputOrderOrAssociationSignificance()throws Exception {
        var policy=Map.<String,Object>of("references",List.of(reference("complete_window")),"maximum_distance_bp",200);var first=apply(context("first",policy));var original=Files.readAllLines(root.resolve("pairs.tsv"));Files.writeString(root.resolve("pairs.tsv"),original.get(0)+"\n"+original.get(3)+"\n"+original.get(2)+"\n"+original.get(1)+"\n");var f=findings();f.get("H\u001frs1").put("significant",false);var c=context("permuted",policy);var second=StudyFindingGrouping.apply(c,f,observations(),Map.of(),new LinkedHashMap<>(),Map.of());assertEquals(component(first,"rs1"),component(second,"rs1"));assertEquals(component(first,"rs3"),component(second,"rs3"));
    }
    @Test void completeWindowWithAnAbsentPairIsHeldAndExplicitPartialUseKeepsKnownEdges()throws Exception {
        var r=reference("complete_window");Files.writeString(root.resolve("pairs.tsv"),"variant_a\tvariant_b\tr_squared\nrs1\trs2\t.81\n");var strict=apply(context("missing-pair",Map.of("references",List.of(r),"maximum_distance_bp",200)));assertEquals(false,strict.summary().get("complete"));assertTrue(strict.assignments().isEmpty());var partial=apply(context("explicit-partial",Map.of("references",List.of(r),"maximum_distance_bp",200,"require_complete_coverage",false)));assertEquals(true,partial.summary().get("complete"));assertEquals("descriptive_partial_reference_components",partial.summary().get("status"));assertNotEquals(component(partial,"rs1"),component(partial,"rs3"));
    }
    @Test void thresholdedCoverageNeedsAdequateWindowAndUnambiguousInclusiveBoundary()throws Exception {
        for(int choice=0;choice<4;choice++){var r=reference("thresholded_window");r.put("minimum_reported_r_squared",choice==0?.2:.8);if(choice>=2)r.put("reporting_comparison","greater_than_or_equal");if(choice==3)r.put("window_bp",199);var result=apply(context("threshold-"+choice,Map.of("references",List.of(r),"maximum_distance_bp",200)));assertEquals(choice==0||choice==2,result.summary().get("complete"));}
    }
    @Test void incompleteVariantCatalogAndWorkBoundsDoNotPublishSuccessfulSubsets()throws Exception {
        var r=reference("complete_window");for(var limit:List.of(Map.of("maximum_pairs",1),Map.of("maximum_variants",1))){var p=new LinkedHashMap<String,Object>(Map.of("references",List.of(r),"maximum_distance_bp",200));p.putAll(limit);var result=apply(context("bound-"+limit.keySet().iterator().next(),p));assertEquals(false,result.summary().get("complete"));assertTrue(result.assignments().isEmpty());}Files.writeString(root.resolve("variants.tsv"),Files.readString(root.resolve("variants.tsv")).replace("rs6\t1\t4000\tA\tG\n",""));var absent=apply(context("absent-variant",Map.of("references",List.of(r),"maximum_distance_bp",200)));assertEquals(false,absent.summary().get("complete"));assertEquals(1,((Number)absent.summary().get("unmatched_eligible_variant_findings")).intValue());
    }
    @Test void invalidAndConflictingLdRowsAreRetainedAsUnavailableInputs()throws Exception {
        var r=reference("complete_window");String original=Files.readString(root.resolve("pairs.tsv"));for(String extra:List.of("rs2\trs1\t.8\n","rs1\tunknown\t.8\n","rs1\trs1\t.5\n","rs1\trs4\t1.1\n")){Files.writeString(root.resolve("pairs.tsv"),original+extra);var result=apply(context("invalid-"+Math.abs(extra.hashCode()),Map.of("references",List.of(r),"maximum_distance_bp",200)));assertEquals(false,result.summary().get("complete"));assertTrue(result.assignments().isEmpty());}
    }
    @Test void primaryAllelesBuildAndKnownPopulationCannotBeSilentlyReassigned()throws Exception {
        var r=reference("complete_window");for(int i=0;i<3;i++){var c=context("identity-"+i,Map.of("references",List.of(r),"maximum_distance_bp",200));var rows=observations();var row=new LinkedHashMap<>(map(rows.get("H\u001frs1").get(0)));if(i==0)row.put("genome_build","GRCh37");if(i==1){row.put("reference_allele","C");row.put("alternate_allele","T");}if(i==2){var study=new LinkedHashMap<>(c.study());study.put("hypotheses",List.of(Map.of("id","H","population","AFR","inputs",Map.of("discovery",List.of("a")))));c=new Context(c.project(),c.outputDirectory(),c.operation(),study,c.plan(),c.dependencyDirectories());}rows.put("H\u001frs1",List.of(row));var result=StudyFindingGrouping.apply(c,findings(),rows,Map.of(),new LinkedHashMap<>(),Map.of());assertEquals(false,result.summary().get("complete"));assertTrue(result.assignments().isEmpty());}
    }
    private void seal(Path directory,String type,String h,Map<String,Object> details)throws Exception {var hashes=new LinkedHashMap<String,Object>();try(var paths=Files.walk(directory)){for(Path p:paths.filter(Files::isRegularFile).filter(p->!p.getFileName().toString().equals("manifest.yaml")).toList())hashes.put(directory.relativize(p).toString().replace('\\','/'),FollowupSupport.hash(p));}write(directory.resolve("manifest.yaml"),Map.of("operation_id",h+"-"+type,"operation_type",type,"hypothesis",h,"state","complete","output_sha256",hashes,"details",details));}
    private Context inventory(String name,boolean missing)throws Exception {
        var r=reference("complete_window");if(missing)r.put("pairs","absent.tsv");var c=context(name,Map.of("references",List.of(r),"maximum_distance_bp",200));Path source=Files.createDirectories(root.resolve("association-"+name).resolve("post-effect-qc-results"));StringBuilder data=new StringBuilder("feature_id\tbeta\tse\tp_value\tN\tstatus\n"),annotation=new StringBuilder("feature_id\tgene_id\tgene_symbol\tmapping_status\n");for(String id:List.of("rs1","rs3","rs4","rs5","rs6")){data.append(id).append("\t.1\t.1\t.000001\t1000\tok\n");annotation.append(id).append("\tGENE-").append(id).append("\tSYM-").append(id).append("\tlocated\n");}Files.writeString(source.resolve("a.tsv"),data);Files.writeString(source.getParent().resolve("feature-annotation.tsv"),annotation);seal(source.getParent(),"association","H",Map.of());return new Context(c.project(),c.outputDirectory(),c.operation(),c.study(),c.plan(),Map.of("association",source.getParent()));
    }
    private List<Map<String,Object>> read(Path directory)throws Exception {var out=new ArrayList<Map<String,Object>>();for(String line:Files.readAllLines(directory.resolve("finding-inventory.jsonl")))out.add(map(SimpleJson.parse(line)));return out;}
    @Test void externalPrimaryScopeDoesNotInheritUnusedRawDatasetIdentity()throws Exception {
        var c=context("external-scope",Map.of("references",List.of(reference("complete_window")),"maximum_distance_bp",200));var study=new LinkedHashMap<>(c.study());study.put("datasets",List.of(Map.of("id","a","type","gwas","genome_build","GRCh37","metadata",Map.of("ancestry","AFR"))));c=new Context(c.project(),c.outputDirectory(),c.operation(),study,c.plan(),c.dependencyDirectories());
        var producer=new StudyPrimaryResults.Producer(root,Map.of("details",Map.of("execution_origin","externally_produced","scope",Map.of("modality","gwas","genome_build","GRCh38","population","EUR"))),"meta_analysis","provided-meta","H");var source=new StudyPrimaryResults.Source(producer,"",root.resolve("unused-meta.tsv"),"fixture");var selected=new StudyPrimaryResults.Selection(source,null,null,Map.of(),Map.of(),Map.of(),"BH","",Map.of());
        var result=StudyFindingGrouping.apply(c,findings(),observations(),Map.of(),new LinkedHashMap<>(),Map.of("H",selected));assertEquals(true,result.summary().get("complete"));assertEquals(5,result.assignments().size());assertEquals(false,apply(c).summary().get("complete"));
    }
    @Test void inventoryKeepsStatisticsAndManualLabelsWhileAddingHashBoundRedundancyEvidence()throws Exception {
        var c=inventory("integrated",false);var result=new StudyFindingInventory().execute(c);assertEquals(State.COMPLETE,result.state());var rows=read(c.outputDirectory());assertEquals(5,rows.size());assertTrue(rows.stream().allMatch(f->Boolean.TRUE.equals(f.get("candidate"))&&text(f.get("story_group")).startsWith("gene:")&&!list(f.get("redundancy_groups")).isEmpty()));var a=rows.stream().filter(f->f.get("feature_id").equals("rs1")).findFirst().orElseThrow();var b=rows.stream().filter(f->f.get("feature_id").equals("rs3")).findFirst().orElseThrow();assertNotEquals(a.get("story_group"),b.get("story_group"));assertEquals(a.get("redundancy_groups"),b.get("redundancy_groups"));assertThrows(IllegalArgumentException.class,()->StudyFindingGrouping.distinct(List.of(a,b)));var independent=rows.stream().filter(f->Set.of("rs1","rs4","rs5").contains(f.get("feature_id"))).toList();assertDoesNotThrow(()->StudyFindingGrouping.distinct(independent));assertTrue(list(a.get("caveats")).stream().map(StudyPublicEvidence::map).anyMatch(x->x.get("kind").equals("ld_grouping")));assertTrue(map(result.details().get("sources")).keySet().stream().anyMatch(id->id.startsWith("source-ld-")));
    }
    @Test void unresolvedGroupingKeepsCandidatesButPreventsAnyModelCall()throws Exception {
        var c=inventory("blocked",true);var result=new StudyFindingInventory().execute(c);assertEquals(State.COMPLETE,result.state());assertEquals(false,map(result.details().get("finding_grouping")).get("complete"));assertEquals(5,read(c.outputDirectory()).stream().filter(f->Boolean.TRUE.equals(f.get("candidate"))).count());seal(c.outputDirectory(),"finding_inventory","__study__",result.details());var calls=new AtomicInteger();var assistant=new StudyAssistance((uri,provider,key,body,timeout)->{calls.incrementAndGet();throw new AssertionError("Grouping prerequisite must precede model transport");},ignored->"fixture");var output=Files.createDirectories(root.resolve("impact-blocked"));var impact=new Context(root,output,Map.of("id","impact","type","impact_assessment"),c.study(),Map.of(),Map.of("inventory",c.outputDirectory()));assertEquals(State.WAITING_FOR_INPUT,new StudyImpactAssessment(assistant).execute(impact).state());assertEquals(0,calls.get());
    }
    @Test void sourceEditsInvalidateInventoryCacheInputsAndDisabledPolicyDoesNotReadReferences()throws Exception {
        var c=context("cache",Map.of("references",List.of(reference("complete_window")),"maximum_distance_bp",200));var before=StudyFindingGroupingResources.inputHashes(root,c.study(),c.operation());Files.writeString(root.resolve("pairs.tsv"),Files.readString(root.resolve("pairs.tsv"))+"rs4\trs5\t.81\n");assertNotEquals(before,StudyFindingGroupingResources.inputHashes(root,c.study(),c.operation()));var disabled=context("disabled",Map.of("enabled",false,"references",List.of(reference("complete_window"))));assertTrue(StudyFindingGroupingResources.inputHashes(root,disabled.study(),disabled.operation()).isEmpty());assertEquals("disabled_by_protocol",apply(disabled).summary().get("status"));
    }
    @Test void malformedGroupingPoliciesAndOverlappingReferenceScopesAreRejected()throws Exception {
        assertThrows(IllegalArgumentException.class,()->StudyFindingGroupingPolicy.resolve(Map.of("minimum_r_squared",1.1)));assertThrows(IllegalArgumentException.class,()->StudyFindingGroupingPolicy.resolve(Map.of("maximum_pairs",0)));assertThrows(IllegalArgumentException.class,()->StudyFindingGroupingPolicy.resolve(Map.of("unknown",true)));var r=reference("complete_window");var duplicate=new LinkedHashMap<>(r);duplicate.put("id","other");assertThrows(IllegalArgumentException.class,()->StudyFindingGroupingPolicy.resolve(Map.of("references",List.of(r,duplicate))));
    }
    @Test void unavailableLdIsNotConvertedToZeroAndCanBeUsedOnlyAsDeclaredPartialEvidence()throws Exception {
        var r=reference("complete_window");Files.writeString(root.resolve("pairs.tsv"),Files.readString(root.resolve("pairs.tsv")).replace("rs2\trs3\t.81","rs2\trs3\tNA"));var strict=apply(context("unknown-ld",Map.of("references",List.of(r),"maximum_distance_bp",200)));assertEquals(false,strict.summary().get("complete"));var partial=apply(context("unknown-partial",Map.of("references",List.of(r),"maximum_distance_bp",200,"require_complete_coverage",false)));assertEquals(true,partial.summary().get("complete"));assertNotEquals(component(partial,"rs1"),component(partial,"rs3"));assertTrue(Files.readString(root.resolve("unknown-partial/finding-grouping/pair-dispositions.tsv")).contains("unavailable_ld_not_zero"));
    }
    private Map<String,Object> answer(List<Map<String,Object>> findings,List<String> selected){var assessments=new ArrayList<Object>();for(var finding:findings){var rubric=new LinkedHashMap<String,Object>();for(String field:StudyImpactAssessment.RUBRIC)rubric.put(field,"Synthetic grouping-contract verification; no biological appraisal.");assessments.add(Map.of("finding_id",finding.get("finding_id"),"rubric",rubric,"evidence_ids",map(finding.get("ld_grouping")).get("source_ids"),"counterevidence_ids",List.of(),"caveat_ids",list(finding.get("caveats")).stream().map(v->map(v).get("id")).toList(),"claim_scope","Source-bound grouping context only"));}return Map.of("assessments",assessments,"selected_ids",selected,"selection_note","","comparison_rationale","Every synthetic candidate considered with the same rubric.");}
    @Test void modelContractCanCiteLdSourcesButCannotUseRenamedCorrelatedStoriesForExtraSlots()throws Exception {
        var c=inventory("model-selection",false);new StudyFindingInventory().execute(c);var findings=read(c.outputDirectory());var byId=new LinkedHashMap<String,String>();for(var finding:findings)byId.put(text(finding.get("feature_id")),text(finding.get("finding_id")));var payload=Map.<String,Object>of("findings",findings,"final_selection",true,"manuscript_policy",Map.of("minimum_findings",3,"maximum_findings",5));assertDoesNotThrow(()->StudyImpactAssessment.validate(payload,answer(findings,List.of(byId.get("rs1"),byId.get("rs4"),byId.get("rs5")))));for(var finding:findings)finding.put("story_group","manually-renamed-"+finding.get("finding_id"));var invalid=answer(findings,List.of(byId.get("rs1"),byId.get("rs3"),byId.get("rs6")));assertTrue(assertThrows(IllegalArgumentException.class,()->StudyImpactAssessment.validate(payload,invalid)).getMessage().contains("LD redundancy"));
    }
    @Test void humanProseReviewRetainsTheSameLdConstraintAsAiSelection()throws Exception {
        var c=inventory("prose",false);var result=new StudyFindingInventory().execute(c);seal(c.outputDirectory(),"finding_inventory","__study__",result.details());var findings=read(c.outputDirectory());var selected=findings.stream().filter(f->Set.of("rs1","rs3").contains(f.get("feature_id"))).map(f->text(f.get("finding_id"))).toList();var evidence=Map.<String,Map<String,Object>>of("inventory",Map.of("operation_type","finding_inventory","state","complete","manifest",root.relativize(c.outputDirectory().resolve("manifest.yaml")).toString()),"impact",Map.of("operation_type","impact_assessment","state","complete","key_findings",Map.of("selected_ids",selected)));var sections=new ArrayList<Object>();sections.add(Map.of("id","results","section","results","finding_ids",selected));for(int i=0;i<selected.size();i++)sections.add(Map.of("id","D"+i,"section","discussion","discussion_role","principal_finding","finding_ids",List.of(selected.get(i)),"result_ids",List.of("results")));assertThrows(java.io.IOException.class,()->StudyImpactNarrative.review(root,Map.of("sections",sections),evidence));
    }
    @Test void retiredReferenceScopesCannotContributeEdgesOrCacheInputs()throws Exception {
        var r=reference("complete_window");r.put("hypotheses",List.of("retired"));r.put("variants","never-open-this.tsv");r.put("pairs","never-open-pairs.tsv");var c=context("retired-ref",Map.of("references",List.of(r),"maximum_distance_bp",200));var study=new LinkedHashMap<>(c.study());var hypotheses=new ArrayList<Object>(list(study.get("hypotheses")));hypotheses.add(Map.of("id","retired","status","retired"));study.put("hypotheses",hypotheses);var current=new Context(c.project(),c.outputDirectory(),c.operation(),study,c.plan(),c.dependencyDirectories());assertTrue(StudyFindingGroupingResources.inputHashes(root,study,current.operation()).isEmpty());var outcome=apply(current);assertEquals(0,outcome.summary().get("active_reference_count"));assertEquals(false,outcome.summary().get("complete"));assertTrue(outcome.assignments().isEmpty());assertFalse(Files.exists(c.outputDirectory().resolve("finding-grouping/panel")));
    }
}
